    } catch (error) {
      if (signal?.aborted) throw abortError(signal);
      fallbacks.push({ provider: provider.name, error: error.message });
    }
  }
  throw new Error(`Web search returned no parseable results. ${fallbacks.map(item => `${item.provider}: ${item.error}`).join(' ')} No results were fabricated.`);
}

const invalidArguments = () => ({ content: [{ type: 'text', text: JSON.stringify({ error: 'invalid-arguments' }) }], details: { error: 'invalid-arguments' } });
const reply = details => ({ content: [{ type: 'text', text: `${UNTRUSTED}\n${JSON.stringify(details)}` }], details });
const plainObject = value => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const onlyKeys = (args, keys) => Object.keys(args).every(key => keys.includes(key));
const nonemptyText = (value, maximum) => typeof value === 'string' && Boolean(value.trim()) && value.length <= maximum;
const optionalInteger = (value, minimum, maximum) => value === undefined || (Number.isSafeInteger(value) && value >= minimum && value <= maximum);
const optionalBoolean = value => value === undefined || typeof value === 'boolean';

function fallbackTitle(url) {
  const { hostname, pathname } = new URL(url);
  const segment = pathname.split('/').filter(Boolean)[0];
  return segment ? `${hostname}/${segment}` : hostname;
}

function fetchFailure(error, url) {
  const message = String(error?.message ?? error).slice(0, 300);
  const status = message.match(/HTTP (\d{3})/);
  if (/private, reserved or non-public/.test(message)) return { error: 'blocked', url, message };
