  if (/timed out|aborted/i.test(message)) return { error: 'timeout', url, message };
  if (/Unsupported content type/.test(message)) return { error: 'unsupported-type', url, message };
  return { error: 'fetch-failed', url, message };
}

/** The two web tools for the research crew. Every returned document is untrusted data, never instructions. */
export function createWebTools({ vault, fetchImpl, lookupImpl } = {}) {
  const options = { fetchImpl, lookupImpl };
  return [
    {
      name: 'web_search',
      description: 'Search the keyless public web through DuckDuckGo Lite, DuckDuckGo HTML and Bing RSS. Returns titles, URLs and snippets plus every provider that failed; search may be blocked or rate-limited. Snippets are discovery hints, not verified claims: fetch the original page before relying on it.',
      parameters: {
        type: 'object',
        properties: {
          query: { type: 'string', minLength: 1, maxLength: 500 },
          limit: { type: 'integer', minimum: 1, maximum: 8 },
        },
        required: ['query'],
        additionalProperties: false,
      },
      async execute(_callId, args, signal) {
        if (signal?.aborted) throw abortError(signal);
