        try {
          const { provider, results, fallbacks } = await searchWeb(args.query, limit, signal, options);
          return reply({ query: args.query, provider, results: results.slice(0, limit), fallbacks });
        } catch (error) {
          if (signal?.aborted) throw abortError(signal);
          return reply({ error: 'search-failed', message: String(error?.message ?? error).slice(0, 300) });
        }
      },
    },
    {
      name: 'fetch_source',
      description: 'Retrieve a public HTTP(S) text, HTML, JSON, XML or RSS page and preserve it in the vault as a citable source. A URL already stored in the vault is returned from the stored copy unless refresh is true. No authenticated browsing, JavaScript execution or PDF retrieval.',
      parameters: {
        type: 'object',
        properties: {
          url: { type: 'string', minLength: 1, maxLength: 4096 },
          refresh: { type: 'boolean' },
        },
        required: ['url'],
        additionalProperties: false,
      },
      async execute(_callId, args, signal) {
        if (signal?.aborted) throw abortError(signal);
        if (!plainObject(args) || !onlyKeys(args, ['url', 'refresh']) || !optionalBoolean(args.refresh)) return invalidArguments();
        let url;
        try { url = parsePublicUrl(args.url).href; } catch { return reply({ error: 'invalid-url', url: args.url }); }
        try {
          const id = await vault.findSourceByUrl(url);
          if (id && args.refresh !== true) {
            const stored = await vault.readSourceText(id);
            if (stored?.text) {
              const link = sourceRef(id, stored.title, id.slice(0, 8));
              return reply({ sourceId: id, ref: link, title: stored.title, url: stored.url, text: stored.text, truncated: false, cached: true, sourceRef: link });
            }
          }
          const page = await retrieve(url, signal, { ...options, requestTimeoutMs: 20000 });
          const html = ['text/html', 'application/xhtml+xml'].includes(page.mimeType);
          const rawTitle = html ? page.body.match(/<title\b[^>]*>([^]*?)<\/title>/i)?.[1] : undefined;
          const title = (rawTitle && htmlText(rawTitle).slice(0, 300)) || fallbackTitle(page.url);
          const full = html ? htmlText(page.body) : page.body;
          if (!full.trim()) return reply({ error: 'fetch-failed', url: page.url, message: 'The page contained no readable text.' });
