          const text = full.slice(0, MAX_TEXT);
          const stored = await vault.storeSource({ url: page.url, title, kind: 'web', text });
          return reply({ sourceId: stored.id, ref: stored.ref, title: stored.title, url: page.url, text, truncated, cached: false });
        } catch (error) {
          if (signal?.aborted) throw abortError(signal);
          return reply(fetchFailure(error, url));
        }
      },
    },
  ];
}
