  async storeSource(record) { const id = `src-${stored.size + 1}`; const row = { ...record, id, path: `Sources/${record.title} (${id}).md`, ref: `[[Sources/${record.title}|${record.title}]]` }; stored.set(record.url, row); return { id, path: row.path, ref: row.ref, title: record.title, reused: false }; },
};

